const updatePerson = `-- name: UpdatePerson :one
UPDATE party.person
   SET first_name = $1,
       middle_name = $2,
       last_name = $3,
       normalized_name = $4,
       birth_date = $5,
       sex_at_birth = $6,
       status = $7,
       updated_by = $8
 WHERE tenant_id = $9
   AND id = $10
   AND row_version = $11
RETURNING row_version
`

type UpdatePersonParams struct {
	FirstName      string
	MiddleName     *string
	LastName       string
	NormalizedName string
	BirthDate      pgtype.Date
	SexAtBirth     *string
	Status         string
	ActorID        uuid.NullUUID
	TenantID       uuid.UUID
	ID             uuid.UUID
	RowVersion     int64
}

// Optimistic concurrency: a stale If-Match matches no row. platform.tg_touch_row bumps
// row_version and updated_at, so this statement never assigns them.
func (q *Queries) UpdatePerson(ctx context.Context, arg UpdatePersonParams) (int64, error) {
	row := q.db.QueryRow(ctx, updatePerson,
		arg.FirstName,
		arg.MiddleName,
		arg.LastName,
		arg.NormalizedName,
		arg.BirthDate,
		arg.SexAtBirth,
		arg.Status,
		arg.ActorID,
		arg.TenantID,
		arg.ID,
		arg.RowVersion,
	)
	var row_version int64
	err := row.Scan(&row_version)
	return row_version, err
}

